<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Database\DB;use StudPulse\Security\Auth;use StudPulse\Http\ApiError;final class Backup{public static function manifest(Auth$a):array{$uid=$a->user['id'];$settings=(new \StudPulse\Http\SettingsController())->get($a);return['format'=>'studpulse-personal','version'=>1,'createdAt'=>gmdate('c'),'ownerId'=>$uid,'preferences'=>$settings['preferences'],'notes'=>DB::all('SELECT id,title,body,revision,updated_at FROM personal_notes WHERE owner_user_id=?',[$uid]),'authoredHomework'=>DB::all('SELECT title,description,due_at,revision FROM homework WHERE author_user_id=? AND deleted_at IS NULL',[$uid]),'materialsMetadata'=>DB::all('SELECT title,description,visibility FROM materials WHERE owner_user_id=? AND deleted_at IS NULL',[$uid]),'excluded'=>['sessions','tokens','credentials','official_grades','attendance','other_users','binary_files']];}public static function preview(Auth$a,array$manifest):array{if(($manifest['format']??'')!=='studpulse-personal'||($manifest['version']??0)!==1||($manifest['ownerId']??'')!==$a->user['id']||!is_array($manifest['notes']??null)||count($manifest['notes'])>1000){throw new ApiError(422,'BACKUP_INVALID','Формат или владелец резервной копии не совпадает');}$notes=[];foreach($manifest['notes']as$n){$notes[]=['originalId'=>Input::id($n['id']??null),'title'=>Input::text($n,'title'),'body'=>Input::text($n,'body',50000,false),'action'=>'create_private_copy'];}return['notes'=>$notes,'preferences'=>Preferences::validate($manifest['preferences']??[]),'policy'=>'Создать новые личные копии заметок. Не затирать существующие записи; групповые публикации не восстанавливаются автоматически.'];}public static function restore(Auth$a,array$manifest):array{$plan=self::preview($a,$manifest);$ids=[];foreach($plan['notes']as$n){$id=DB::id();DB::run('INSERT INTO personal_notes(id,owner_user_id,title,body) VALUES(?,?,?,?)',[$id,$a->user['id'],$n['title'],$n['body']]);$ids[]=$id;}return['createdNotes'=>$ids,'settingsApplied'=>false,'message'=>'Личные копии созданы. Настройки показаны в предпросмотре и применяются отдельно.'];}}